1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Customer {
23	  yearsWithMHPCO: number;
24	}
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type QuoteResult = { premium: number };
32	export type ClaimResult = { payout: number; remainingCap: number };
33	export type Result = QuoteResult | ClaimResult;
34	
35	export interface ScenarioOutcome {
36	  results: Result[];
37	}
38	
39	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
40	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
41	
42	const BASE_PREMIUM: Record<string, number> = {
43	  sword: 100,
44	  amulet: 60,
45	  staff: 80,
46	  potion: 40,
47	  rune: 25,
48	  moonstone: 25,
49	};
50	
51	const INSURANCE_VALUE: Record<string, number> = {
52	  sword: 1000,
53	  amulet: 600,
54	  staff: 800,
55	  potion: 400,
56	  rune: 250,
57	  moonstone: 250,
58	};
59	
60	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
61	const POLICY_FEE = 5;
62	
63	const COMPONENT_TYPES = ["rune", "moonstone"];
64	const BUILDING_BLOCK_SIZE = 3;
65	const BUILDING_BLOCK_BASE_PREMIUM = 60;
66	
67	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
68	
69	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
70	
71	const countOfType = (items: Item[], type: string): number =>
72	  items.filter((item) => item.type === type).length;
73	
74	/**
75	 * Components of one kind are bundled into building blocks of 3, each charged at
76	 * the special block rate; leftovers are charged individually.
77	 */
78	const componentGroupBasePremium = (type: string, count: number): number => {
79	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
80	  const singles = count % BUILDING_BLOCK_SIZE;
81	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
82	};
83	
84	const CURSED_SURCHARGE_RATE = 0.5;
85	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
86	/**
87	 * The quote-side threshold. Independent of HIGH_ENCHANTMENT_CLAIM_LEVEL: an item at
88	 * enchantment 7 carries the surcharge here but is still reimbursed in full on a claim.
89	 */
90	const HIGH_ENCHANTMENT_QUOTE_LEVEL = 5;
91	
92	/**
93	 * A premium modifier as a multiplicative factor: a positive rate loads the premium,
94	 * a negative rate discounts it, and a modifier that does not apply leaves it untouched.
95	 */
96	const rateFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
97	
98	const isCursed = (item: Item): boolean => item.cursed === true;
99	const isHighlyEnchanted = (item: Item): boolean =>
100	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_QUOTE_LEVEL;
101	
102	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
103	const riskMultiplierOf = (item: Item): number =>
104	  rateFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
105	  rateFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
106	
107	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
108	const mainItemsPremium = (items: Item[]): number =>
109	  sum(
110	    items
111	      .filter((item) => !isComponent(item))
112	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
113	  );
114	
115	/**
116	 * Components are priced per kind, so alike ones can bundle into building blocks.
117	 * Pricing by count means individual risk flags are not visible here — no test covers
118	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
119	 */
120	const componentsPremium = (items: Item[]): number =>
121	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
122	
123	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
124	const riskLoadedPremiumOf = (items: Item[]): number =>
125	  mainItemsPremium(items) + componentsPremium(items);
126	
127	const LOYALTY_DISCOUNT_RATE = -0.2;
128	/** Loyalty begins at the start of the second year: 1 year does not qualify, 2 do. */
129	const LOYALTY_THRESHOLD_YEARS = 2;
130	
131	const isLoyal = (customer: Customer): boolean =>
132	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
133	
134	const CONTRACT_DISCOUNT_RATE = -0.15;
135	
136	/**
137	 * Customer-level modifiers apply to the whole quote and compound. A customer's very
138	 * first insurance carries the assessment surcharge; every contract after it is
139	 * discounted instead. `previousQuotes` counts quotes already given to this customer.
140	 */
141	const customerMultiplierOf = (customer: Customer, previousQuotes: number): number => {
142	  const isFirstInsurance = previousQuotes === 0;
143	  return (
144	    rateFactor(isLoyal(customer), LOYALTY_DISCOUNT_RATE) *
145	    rateFactor(isFirstInsurance, FIRST_INSURANCE_SURCHARGE_RATE) *
146	    rateFactor(!isFirstInsurance, CONTRACT_DISCOUNT_RATE)
147	  );
148	};
149	
150	const quote = (items: Item[], customer: Customer, previousQuotes: number): QuoteResult => {
151	  const premiumBeforeFee =
152	    riskLoadedPremiumOf(items) * customerMultiplierOf(customer, previousQuotes);
153	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
154	};
155	
156	/**
157	 * Steps are not independent: each one is answered in the light of the steps before it,
158	 * so the scenario is walked as a fold that threads what has happened so far.
159	 */
160	interface Policy {
161	  items: Item[];
162	  remainingCap: number;
163	}
164	
165	interface ScenarioState {
166	  quotesSoFar: number;
167	  /** Policies issued so far, keyed by the step index of the quote that created each. */
168	  policies: Record<number, Policy>;
169	}
170	
171	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, policies: {} };
172	
173	const DEDUCTIBLE = 100;
174	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
175	
176	const insuranceSumOf = (items: Item[]): number =>
177	  sum(items.map((item) => INSURANCE_VALUE[item.type]));
178	
179	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
180	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
181	const FULL_REIMBURSEMENT_RATE = 1;
182	
183	const DRAGON_MATERIAL = "dragon";
184	
185	const isDragonMade = (item: Item): boolean => item.material === DRAGON_MATERIAL;
186	
187	/**
188	 * The claim-side threshold, named separately from isHighlyEnchanted so the two
189	 * thresholds can move independently: an item at enchantment 7 carries the quote
190	 * surcharge but is still reimbursed in full here.
191	 */
192	const isHeavilyEnchanted = (item: Item): boolean =>
193	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
194	
195	/**
196	 * Heavily enchanted items are only half covered — but dragon-made ones are reimbursed
197	 * in full regardless, the MHPCO holding dragon craftsmanship beyond reproach.
198	 */
199	const reimbursementRateOf = (item: Item): number =>
200	  isHeavilyEnchanted(item) && !isDragonMade(item)
201	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
202	    : FULL_REIMBURSEMENT_RATE;
203	
204	/**
205	 * A damage names its item by type. A damage naming a type the policy does not cover is
206	 * outside anything the specification describes, so it is reimbursed at the plain rate
207	 * rather than given a rule of its own.
208	 */
209	const rateForDamage = (damage: Damage, items: Item[]): number => {
210	  const damagedItem = items.find((item) => item.type === damage.itemType);
211	  return damagedItem === undefined ? FULL_REIMBURSEMENT_RATE : reimbursementRateOf(damagedItem);
212	};
213	
214	/**
215	 * Each damage is reimbursed at the rate its own item earns, and the deductible is borne
216	 * by the incident as a whole — so the rates are applied first and the sum reduced once.
217	 */
218	const reimbursableDamageOf = (incident: Incident, items: Item[]): number =>
219	  sum(incident.damages.map((damage) => damage.amount * rateForDamage(damage, items)));
220	
221	/** Draws the payout down against the policy's remaining cap, reporting what is left. */
222	const settleClaimAgainstCap = (incident: Incident, policy: Policy): ClaimResult => {
223	  const claimed = Math.max(0, reimbursableDamageOf(incident, policy.items) - DEDUCTIBLE);
224	  const payout = Math.min(claimed, policy.remainingCap);
225	  return { payout, remainingCap: policy.remainingCap - payout };
226	};
227	
228	/** Records a policy under its step index, leaving the rest of the scenario state untouched. */
229	const withPolicy = (state: ScenarioState, policyKey: number, policy: Policy): ScenarioState => ({
230	  ...state,
231	  policies: { ...state.policies, [policyKey]: policy },
232	});
233	
234	const applyStep = (
235	  state: ScenarioState,
236	  step: Step,
237	  customer: Customer,
238	  stepIndex: number,
239	): { state: ScenarioState; result: Result } => {
240	  if (step.op === "quote") {
241	    const policy: Policy = {
242	      items: step.items,
243	      remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items),
244	    };
245	    return {
246	      state: withPolicy({ ...state, quotesSoFar: state.quotesSoFar + 1 }, stepIndex, policy),
247	      result: quote(step.items, customer, state.quotesSoFar),
248	    };
249	  }
250	  const policy = state.policies[step.policy];
251	  const result = settleClaimAgainstCap(step.incident, policy);
252	  return {
253	    state: withPolicy(state, step.policy, { ...policy, remainingCap: result.remainingCap }),
254	    result,
255	  };
256	};
257	
258	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
259	  const results: Result[] = [];
260	  let state = INITIAL_STATE;
261	  for (const [stepIndex, step] of scenario.steps.entries()) {
262	    const stepOutcome = applyStep(state, step, scenario.customer, stepIndex);
263	    state = stepOutcome.state;
264	    results.push(stepOutcome.result);
265	  }
266	  return { results };
267	};
